from datetime import datetime, timedelta
import json
import pytz

Remote = self.remote_id
Sensor = env['mdm.measurement.device.sensor']
Reading = env['mdm.measurement.device.sensor.reading']
madrid_tz = pytz.timezone('Europe/Madrid')
now_local = datetime.now(madrid_tz).replace(tzinfo=None)


def _json_loads(raw_value):
    try:
        return json.loads(raw_value or '{}') or {}
    except Exception:
        return {}


def _parse_local_datetime(raw_value):
    raw_value = (raw_value or '').strip()
    if not raw_value:
        return False
    candidates = (
        (raw_value[:19], '%Y-%m-%dT%H:%M:%S'),
        (raw_value[:19], '%Y-%m-%d %H:%M:%S'),
        (raw_value[:10], '%Y-%m-%d'),
    )
    for candidate, fmt in candidates:
        try:
            return datetime.strptime(candidate, fmt)
        except Exception:
            continue
    return False


def _utc_string_to_local_datetime(raw_value):
    if not raw_value:
        return False
    utc_dt = fields.Datetime.from_string(raw_value)
    return pytz.UTC.localize(utc_dt).astimezone(
        madrid_tz).replace(tzinfo=None)


remote_cfg = _json_loads(Remote.connection_params)
default_start_dt = _parse_local_datetime(
    remote_cfg.get('default_start_date') or remote_cfg.get('start_date'))
if not default_start_dt:
    default_start_dt = now_local.replace(
        hour=0, minute=0, second=0, microsecond=0)

domain = [
    ('active', '=', True),
    ('device_id.active', '=', True),
    ('device_id.remotecontrol_id', '=', Remote.id),
]
if selected_device_ids:
    domain.append(('device_id', 'in', selected_device_ids))

sensors = Sensor.search(domain, order='device_id, name')
sensors_plan = []
skipped = []

for sensor in sensors:
    device = sensor.device_id
    device_cfg = _json_loads(device.remotecontrol_params)
    sensor_cfg = _json_loads(sensor.remotecontrol_params)
    signal = (
        sensor_cfg.get('senal') or
        sensor_cfg.get('signal') or
        sensor_cfg.get('tag') or
        ''
    ).strip()

    if not signal:
        skipped.append({
            'sensor_id': sensor.id,
            'sensor_name': sensor.name,
            'device_id': device.id,
            'device_name': device.name,
            'reason': 'Missing senal in sensor remotecontrol_params.',
        })
        continue

    last_reading = Reading.search([
        ('sensor_id', '=', sensor.id),
        ('active', '=', True),
    ], order='measurement_time desc', limit=1)
    if last_reading and last_reading.measurement_time:
        start_dt = _utc_string_to_local_datetime(
            last_reading.measurement_time) + timedelta(minutes=15)
    else:
        start_dt = _parse_local_datetime(
            sensor_cfg.get('start_date') or
            device_cfg.get('start_date')
        ) or default_start_dt

    if start_dt > now_local:
        continue

    sensors_plan.append({
        'sensor_id': sensor.id,
        'sensor_name': sensor.name,
        'device_id': device.id,
        'device_name': device.name,
        'senal': signal,
        'start_dt': start_dt.strftime('%Y-%m-%d %H:%M:%S'),
        'end_dt': now_local.strftime('%Y-%m-%d %H:%M:%S'),
    })

bag['sensors_plan'] = sensors_plan
bag['skipped_sensors'] = skipped
bag['total_sensors'] = len(sensors_plan)
bag['skipped_sensors_count'] = len(skipped)
result = 'Built plan for %d SAIH Ebro sensors' % len(sensors_plan)

from datetime import datetime
from datetime import timedelta
import json

sensors_plan = bag.get('sensors_plan') or []
if not sensors_plan:
    raise Exception('No sensors in plan (check Build Plan step)')

Remote = self.remote_id
try:
    remote_cfg = json.loads(Remote.connection_params or '{}') or {}
except Exception:
    remote_cfg = {}

api_key = (remote_cfg.get('api_key') or '').strip()
if not api_key:
    raise Exception('Missing api_key in SAIH Ebro connection_params')


def _parse_datetime(raw_value):
    return datetime.strptime(raw_value, '%Y-%m-%d %H:%M:%S')


def _parse_reading_datetime(raw_value):
    if not raw_value:
        return False
    for fmt in ('%Y-%m-%d %H:%M:%S', '%Y-%m-%dT%H:%M:%S'):
        try:
            return datetime.strptime(raw_value[:19], fmt)
        except Exception:
            continue
    return False


endpoint = '/datos/apiopendata'
url = '%s%s' % ((base_url or '').rstrip('/'), endpoint)

readings = []
api_calls = []
errors = []

for item in sensors_plan:
    signal = item['senal']
    sensor_id = item['sensor_id']
    start_dt = _parse_datetime(item['start_dt'])
    end_dt = _parse_datetime(item['end_dt'])
    current_dt = start_dt

    while current_dt <= end_dt:
        inicio = current_dt.strftime('%Y-%m-%dT%H:%M:%S')
        params = {
            'senal': signal,
            'inicio': inicio,
            'apikey': api_key,
        }
        resp = request_retry('GET', url, params=params, timeout=timeout)
        api_calls.append({
            'url': getattr(resp, 'url', url),
            'method': 'GET',
            'status': resp.status_code,
            'senal': signal,
            'inicio': inicio,
        })

        if resp.status_code >= 400:
            errors.append(
                'API error for signal %s at %s: %s' % (
                    signal, inicio, resp.status_code))
            current_dt += timedelta(hours=24)
            continue

        try:
            payload = resp.json() or {}
        except Exception as e:
            errors.append(
                'JSON parse error for signal %s at %s: %s' % (
                    signal, inicio, str(e)))
            current_dt += timedelta(hours=24)
            continue

        signal_readings = payload.get('senales') or []
        if not isinstance(signal_readings, list):
            errors.append(
                'Invalid readings response for signal %s at %s' % (
                    signal, inicio))
            current_dt += timedelta(hours=24)
            continue

        for reading in signal_readings:
            if not isinstance(reading, dict):
                continue
            if (reading.get('senal') or '').strip() != signal:
                continue

            timestamp_str = reading.get('fecha') or ''
            reading_dt = _parse_reading_datetime(timestamp_str)
            if not reading_dt:
                errors.append(
                    'Invalid timestamp for signal %s: %s' % (
                        signal, timestamp_str))
                continue
            if reading_dt < start_dt or reading_dt > end_dt:
                continue

            value_raw = reading.get('valor')
            if isinstance(value_raw, basestring):
                value_raw = value_raw.replace(',', '.')
            try:
                value = float(value_raw)
            except (ValueError, TypeError):
                errors.append(
                    'Invalid value for signal %s: %s' % (signal, value_raw))
                continue

            readings.append({
                'sensor_id': sensor_id,
                'value': value,
                'timestamp': timestamp_str,
                'senal': signal,
                'unit': reading.get('unidades') or '',
                'description': reading.get('descripcion') or '',
                'trend': reading.get('tendencia') or '',
            })

        current_dt += timedelta(hours=24)

bag['readings'] = readings
bag['total_readings'] = len(readings)
bag['api_calls'] = api_calls
if errors:
    bag['fetch_errors'] = errors

result = 'Fetched %d readings from SAIH Ebro' % len(readings)
